contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    fallback() external payable {
        // Answer access-control style queries (e.g. hasRole) affirmatively so
        // this contract can act as LRTConfig and pass the admin check.
        assembly {
            mstore(0, 1)
            return(0, 32)
        }
    }

    receive() external payable {}

    function run(address[] calldata arr) public {
        c.initialize(address(this));
        uint256 before = c.getNodeDelegatorQueue().length;
        bool reverted;
        try c.addNodeDelegatorContractToQueue(arr) {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 afterL = c.getNodeDelegatorQueue().length;
        assert(
            afterL <= c.maxNodeDelegatorCount() &&
            (reverted ? afterL == before : afterL == before + arr.length)
        );
    }
}

