contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Lets C see this contract as an AccessControl admin (hasRole always returns true).
    fallback() external payable {
        if (msg.sig == IAccessControl.hasRole.selector) {
            assembly {
                mstore(0x00, 0x01)
                return(0x00, 0x20)
            }
        }
    }

    function run(address[] calldata candidates, uint256 maxCount) public payable {
        uint256 n = candidates.length;
        for (uint256 i; i < n; ++i) {
            require(candidates[i] != address(0));
        }
        c.initialize(address(this));
        c.updateMaxNodeDelegatorCount(maxCount);
        uint256 lenBefore = c.getNodeDelegatorQueue().length;
        bool reverted;
        try c.addNodeDelegatorContractToQueue(candidates) {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 lenAfter = c.getNodeDelegatorQueue().length;
        if (lenBefore + n <= maxCount) {
            assert(!reverted && lenAfter == lenBefore + n);
        } else {
            assert(reverted && lenAfter == lenBefore);
        }
    }
    receive() external payable {}
}

